public class InnerAIAgentAIAgentConfigurationFactory(Action<Humidifier.Wisdom.AIAgentTypes.AIAgentConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Wisdom.AIAgentTypes.AIAgentConfiguration>
{

    internal InnerAIAgentCaseSummarizationAIAgentConfigurationFactory CaseSummarizationAIAgentConfigurationFactory { get; set; }

    internal InnerAIAgentManualSearchAIAgentConfigurationFactory ManualSearchAIAgentConfigurationFactory { get; set; }

    internal InnerAIAgentEmailOverviewAIAgentConfigurationFactory EmailOverviewAIAgentConfigurationFactory { get; set; }

    internal InnerAIAgentOrchestrationAIAgentConfigurationFactory OrchestrationAIAgentConfigurationFactory { get; set; }

    internal InnerAIAgentSelfServiceAIAgentConfigurationFactory SelfServiceAIAgentConfigurationFactory { get; set; }

    internal InnerAIAgentEmailResponseAIAgentConfigurationFactory EmailResponseAIAgentConfigurationFactory { get; set; }

    internal InnerAIAgentNoteTakingAIAgentConfigurationFactory NoteTakingAIAgentConfigurationFactory { get; set; }

    internal InnerAIAgentAnswerRecommendationAIAgentConfigurationFactory AnswerRecommendationAIAgentConfigurationFactory { get; set; }

    internal InnerAIAgentEmailGenerativeAnswerAIAgentConfigurationFactory EmailGenerativeAnswerAIAgentConfigurationFactory { get; set; }

    protected override Humidifier.Wisdom.AIAgentTypes.AIAgentConfiguration Create()
    {
        var aIAgentConfigurationResult = CreateAIAgentConfiguration();
        factoryAction?.Invoke(aIAgentConfigurationResult);

        return aIAgentConfigurationResult;
    }

    private Humidifier.Wisdom.AIAgentTypes.AIAgentConfiguration CreateAIAgentConfiguration()
    {
        var aIAgentConfigurationResult = new Humidifier.Wisdom.AIAgentTypes.AIAgentConfiguration();

        return aIAgentConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Wisdom.AIAgentTypes.AIAgentConfiguration result)
    {
        base.CreateChildren(result);

        result.CaseSummarizationAIAgentConfiguration ??= CaseSummarizationAIAgentConfigurationFactory?.Build();
        result.ManualSearchAIAgentConfiguration ??= ManualSearchAIAgentConfigurationFactory?.Build();
        result.EmailOverviewAIAgentConfiguration ??= EmailOverviewAIAgentConfigurationFactory?.Build();
        result.OrchestrationAIAgentConfiguration ??= OrchestrationAIAgentConfigurationFactory?.Build();
        result.SelfServiceAIAgentConfiguration ??= SelfServiceAIAgentConfigurationFactory?.Build();
        result.EmailResponseAIAgentConfiguration ??= EmailResponseAIAgentConfigurationFactory?.Build();
        result.NoteTakingAIAgentConfiguration ??= NoteTakingAIAgentConfigurationFactory?.Build();
        result.AnswerRecommendationAIAgentConfiguration ??= AnswerRecommendationAIAgentConfigurationFactory?.Build();
        result.EmailGenerativeAnswerAIAgentConfiguration ??= EmailGenerativeAnswerAIAgentConfigurationFactory?.Build();
    }

} // End Of Class

